import{_ as p,I as n,o as c,c as m,b6 as t,j as e,J as i,w as l,a as s}from"./chunks/framework.BUXTSoD9.js";const v=JSON.parse('{"title":"Online Exam & Management System","description":"","frontmatter":{},"headers":[],"relativePath":"en/stage-2/assignments/exam-management-express/index.md","filePath":"en/stage-2/assignments/exam-management-express/index.md"}'),h={name:"en/stage-2/assignments/exam-management-express/index.md"},u={style:{margin:"32px 0"}};function b(g,a,k,f,x,y){const r=n("StepBar"),o=n("ClientOnly"),d=n("el-card");return c(),m("div",null,[a[2]||(a[2]=t('<h1 id="online-exam-management-system" tabindex="-1">Online Exam &amp; Management System <a class="header-anchor" href="#online-exam-management-system" aria-label="Permalink to “Online Exam &amp; Management System”">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>This project requires you to build an online exam and management system from scratch, based on a real PRD. What makes this project special is its multi-role design — students and admins see different pages and can perform different actions. You&#39;ll use Express to build the backend, implementing the complete exam business pipeline.</p><p>This is the comprehensive practical section of Stage 2. Multi-role permission systems are very common in real-world applications. Once you master this pattern, you&#39;ll be able to handle education, SaaS, and admin management scenarios of all kinds.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to “Prerequisites”">​</a></h2><p>Before starting this project, you should already be familiar with:</p><ul><li>Frontend page design and component libraries (<a href="./../../frontend/ui-design/">UI Design</a>, <a href="./../../frontend/modern-component-library/">Modern Component Libraries</a>)</li><li>Backend API design and development (<a href="./../../backend/ai-interface-code/">API Code</a>)</li><li>Database fundamentals and Supabase (<a href="./../../backend/database-supabase/">Database to Supabase</a>)</li><li>Git workflow and deployment (<a href="./../../backend/git-workflow/">Git &amp; GitHub</a>, <a href="./../../backend/zeabur-deployment/">Web App Deployment</a>)</li></ul><h2 id="learning-objectives" tabindex="-1">Learning Objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to “Learning Objectives”">​</a></h2><p>After completing this project, you will be able to:</p><ol><li>Read and understand a real PRD, extracting a development task list</li><li>Design permission control and page routing for multi-role systems</li><li>Build a complete backend API using Express</li><li>Implement the exam, submission, and auto-grading business pipeline</li><li>Complete end-to-end integration and deliver a demo-ready business system prototype</li></ol><h2 id="project-overview" tabindex="-1">Project Overview <a class="header-anchor" href="#project-overview" aria-label="Permalink to “Project Overview”">​</a></h2><p>You will build an online exam and management system with three subsystems:</p><table tabindex="0"><thead><tr><th>Subsystem</th><th>Responsibility</th></tr></thead><tbody><tr><td><strong>Public Website</strong></td><td>Platform introduction, login entry</td></tr><tr><td><strong>Student Portal</strong></td><td>Exam list, taking exams, submission, grade viewing</td></tr><tr><td><strong>Admin Dashboard</strong></td><td>Question bank management, exam management, submission records, grade statistics</td></tr></tbody></table><p>The backend uses Express and needs to support: login auth, role permissions, exam and question bank management, submission flow with auto-grading, and grade/statistics management.</p><div class="tip custom-block"><p class="custom-block-title">PRD</p><p>The requirements document for this project is on GitHub: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/en/stage-2/assignments/exam-management-express/PRD.md" target="_blank" rel="noreferrer">View PRD</a></p></div>',15)),e("div",u,[i(o,null,{default:l(()=>[i(r,{active:0,items:[{title:"Requirements",description:"Read PRD, define roles, pages, exam flow, and data models"},{title:"Scaffold",description:"Use AI to generate student and admin page skeletons"},{title:"Backend",description:"Connect login, exams, submission, and grading with Express"},{title:"Launch",description:"End-to-end testing, deploy, and prepare demo"}]})]),_:1})]),a[3]||(a[3]=t(`<h2 id="part-1-requirements-analysis" tabindex="-1">Part 1: Requirements Analysis <a class="header-anchor" href="#part-1-requirements-analysis" aria-label="Permalink to “Part 1: Requirements Analysis”">​</a></h2><h3 id="_1-1-read-the-prd" tabindex="-1">1.1 Read the PRD <a class="header-anchor" href="#_1-1-read-the-prd" aria-label="Permalink to “1.1 Read the PRD”">​</a></h3><p>Open the PRD document and answer these key questions:</p><ul><li>How many roles does the system have? What can each role do?</li><li>Is the page list complete? What pages do the student portal and admin dashboard each have?</li><li>What question types are supported? What is the grading logic for each type?</li><li>What is the complete exam flow? (Publish → Start → Answer → Submit → Grade → View results)</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>If the above questions don&#39;t have clear answers, don&#39;t start coding. Unclear requirements are the most common cause of rework.</p></div><h3 id="_1-2-confirm-system-architecture" tabindex="-1">1.2 Confirm System Architecture <a class="header-anchor" href="#_1-2-confirm-system-architecture" aria-label="Permalink to “1.2 Confirm System Architecture”">​</a></h3><p>Map out the overall architecture based on the PRD:</p><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; web[&quot;Public Website&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; student[&quot;Student Portal&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; admin[&quot;Admin Dashboard&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  student --&gt; auth[&quot;Auth&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  student --&gt; exam[&quot;Exam &amp; Answering&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  exam --&gt; db[&quot;Database&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; question[&quot;Question Bank&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; submission[&quot;Submissions &amp; Grades&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  question --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  submission --&gt; db</span></span></code></pre></div><h2 id="part-2-project-scaffolding" tabindex="-1">Part 2: Project Scaffolding <a class="header-anchor" href="#part-2-project-scaffolding" aria-label="Permalink to “Part 2: Project Scaffolding”">​</a></h2><h3 id="_2-1-generate-frontend-pages" tabindex="-1">2.1 Generate Frontend Pages <a class="header-anchor" href="#_2-1-generate-frontend-pages" aria-label="Permalink to “2.1 Generate Frontend Pages”">​</a></h3><p>Prompt reference:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Based on the current PRD, help me generate a frontend scaffold for an online exam and management system.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Tech stack:</span></span>
<span class="line"><span>- Next.js App Router</span></span>
<span class="line"><span>- TypeScript</span></span>
<span class="line"><span>- Tailwind CSS</span></span>
<span class="line"><span>- shadcn/ui</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Page list:</span></span>
<span class="line"><span>1. Homepage /</span></span>
<span class="line"><span>2. Login page /login</span></span>
<span class="line"><span>3. Student exam list /student/exams</span></span>
<span class="line"><span>4. Student exam taking /student/exams/[id]</span></span>
<span class="line"><span>5. Student grades /student/history</span></span>
<span class="line"><span>6. Admin dashboard /admin</span></span>
<span class="line"><span>7. Exam management /admin/exams</span></span>
<span class="line"><span>8. Question bank /admin/questions</span></span>
<span class="line"><span>9. Submission records /admin/submissions</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Requirements:</span></span>
<span class="line"><span>- Student pages should be clean, focused, and easy to answer questions on</span></span>
<span class="line"><span>- Admin pages should use sidebar + top bar layout</span></span>
<span class="line"><span>- Use mock data first, no real API integration</span></span>
<span class="line"><span>- Ensure basic usability on both desktop and mobile</span></span></code></pre></div><h3 id="_2-2-refine-the-student-exam-page" tabindex="-1">2.2 Refine the Student Exam Page <a class="header-anchor" href="#_2-2-refine-the-student-exam-page" aria-label="Permalink to “2.2 Refine the Student Exam Page”">​</a></h3><p>The exam-taking page is the core of the student portal. Focus on refining it:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Continue refining the student exam-taking page.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>This is an exam-taking page for an online exam system, it should include:</span></span>
<span class="line"><span>- Top bar: exam title, countdown timer, number of answered questions</span></span>
<span class="line"><span>- Main area: question stem and options</span></span>
<span class="line"><span>- Support three question types: single choice, true/false, short answer</span></span>
<span class="line"><span>- Answer card on the left or top showing which questions have been answered</span></span>
<span class="line"><span>- Confirmation dialog before submission</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Use mock data for interactions first, no real API.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Requirements:</span></span>
<span class="line"><span>- Clean interface, shouldn&#39;t look like a backend table page</span></span>
<span class="line"><span>- Countdown should be prominent but not overly stressful</span></span>
<span class="line"><span>- Include empty states and loading states</span></span></code></pre></div><h3 id="_2-3-refine-the-admin-dashboard" tabindex="-1">2.3 Refine the Admin Dashboard <a class="header-anchor" href="#_2-3-refine-the-admin-dashboard" aria-label="Permalink to “2.3 Refine the Admin Dashboard”">​</a></h3><p>The first version of the admin dashboard focuses on three core areas:</p><ul><li><strong>Exam Management</strong>: Create exams, set duration, manage publish status</li><li><strong>Question Bank</strong>: Add questions, edit questions, filter by type</li><li><strong>Submission Records</strong>: View student submissions, scores, timestamps</li></ul><h3 id="_2-4-verify-page-structure" tabindex="-1">2.4 Verify Page Structure <a class="header-anchor" href="#_2-4-verify-page-structure" aria-label="Permalink to “2.4 Verify Page Structure”">​</a></h3><p>Check each item:</p><ul><li>[ ] Student and admin entry points are separate</li><li>[ ] Login, exam list, exam-taking, and grades pages are complete</li><li>[ ] Admin question bank, exam management, and submission records pages are accessible</li><li>[ ] Student and admin page styles are clearly differentiated</li></ul><h3 id="stuck" tabindex="-1">Stuck? <a class="header-anchor" href="#stuck" aria-label="Permalink to “Stuck?”">​</a></h3><p>If you get stuck during frontend scaffolding, review these chapters:</p><ul><li><a href="./../../backend/database-supabase/">Database to Supabase</a></li><li><a href="./../../backend/ai-interface-code/">Backend API Design &amp; Development</a></li><li><a href="./../../frontend/modern-component-library/">Modern Component Libraries</a></li></ul><h2 id="part-3-backend-development" tabindex="-1">Part 3: Backend Development <a class="header-anchor" href="#part-3-backend-development" aria-label="Permalink to “Part 3: Backend Development”">​</a></h2><h3 id="_3-1-login-permission-control" tabindex="-1">3.1 Login &amp; Permission Control <a class="header-anchor" href="#_3-1-login-permission-control" aria-label="Permalink to “3.1 Login &amp; Permission Control”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Treat me as a beginner and help me implement login and permission control for the online exam system.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Backend: Express.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Goals:</span></span>
<span class="line"><span>1. Both students and admins can log in</span></span>
<span class="line"><span>2. Login returns the user&#39;s role</span></span>
<span class="line"><span>3. Students can only access /student/* APIs</span></span>
<span class="line"><span>4. Admins can only access /admin/* APIs</span></span>
<span class="line"><span>5. Unauthenticated users accessing protected pages redirect to /login</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Requirements:</span></span>
<span class="line"><span>- Suggest a clear directory structure</span></span>
<span class="line"><span>- Explain what the middleware is responsible for</span></span>
<span class="line"><span>- Don&#39;t hardcode environment variables</span></span>
<span class="line"><span>- Explain how to verify permissions work after implementation</span></span></code></pre></div><h3 id="_3-2-exam-question-bank-apis" tabindex="-1">3.2 Exam &amp; Question Bank APIs <a class="header-anchor" href="#_3-2-exam-question-bank-apis" aria-label="Permalink to “3.2 Exam &amp; Question Bank APIs”">​</a></h3><p>Recommended implementation by module:</p><table tabindex="0"><thead><tr><th>Module</th><th>Suggested APIs</th></tr></thead><tbody><tr><td>Exam Management</td><td><code>GET /api/exams</code>, <code>POST /api/admin/exams</code>, <code>PATCH /api/admin/exams/:id</code></td></tr><tr><td>Question Bank</td><td><code>GET /api/admin/questions</code>, <code>POST /api/admin/questions</code></td></tr><tr><td>Start Exam</td><td><code>POST /api/submissions/start</code></td></tr><tr><td>Submit Exam</td><td><code>POST /api/submissions/:id/submit</code></td></tr><tr><td>Grade Records</td><td><code>GET /api/student/history</code>, <code>GET /api/admin/submissions</code></td></tr></tbody></table><p>Prompt reference:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Help me design and implement Express APIs for the online exam system.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Scope:</span></span>
<span class="line"><span>- Admin creates exams</span></span>
<span class="line"><span>- Admin manages question bank</span></span>
<span class="line"><span>- Students view published exams</span></span>
<span class="line"><span>- Students start exam and create submission</span></span>
<span class="line"><span>- Student submissions auto-grade multiple choice and true/false</span></span>
<span class="line"><span>- Short answer questions marked as pending review</span></span>
<span class="line"><span>- Students view their grade history</span></span>
<span class="line"><span>- Admins view all submission records</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Requirements:</span></span>
<span class="line"><span>- Clear API naming</span></span>
<span class="line"><span>- Unified JSON response structure</span></span>
<span class="line"><span>- Separate code into controller, service, middleware, and db layers</span></span>
<span class="line"><span>- Explain how to test each API</span></span></code></pre></div><h3 id="_3-3-grading-logic" tabindex="-1">3.3 Grading Logic <a class="header-anchor" href="#_3-3-grading-logic" aria-label="Permalink to “3.3 Grading Logic”">​</a></h3><p>Grading logic is the core business rule of the exam system:</p><ul><li><strong>Multiple Choice</strong>: Score if the user&#39;s answer matches the correct answer</li><li><strong>True/False</strong>: Can also be auto-graded</li><li><strong>Short Answer</strong>: First version just saves the answer, score is null, status is <code>reviewed = false</code></li></ul><div class="tip custom-block"><p class="custom-block-title">Bonus</p><p>If you want to add AI capabilities, you could let admins enter &quot;topic + difficulty&quot; and have the model generate candidate questions for manual review before adding to the bank. But this is a bonus, not required.</p></div><h2 id="part-4-integration-launch" tabindex="-1">Part 4: Integration &amp; Launch <a class="header-anchor" href="#part-4-integration-launch" aria-label="Permalink to “Part 4: Integration &amp; Launch”">​</a></h2><h3 id="_4-1-end-to-end-testing" tabindex="-1">4.1 End-to-End Testing <a class="header-anchor" href="#_4-1-end-to-end-testing" aria-label="Permalink to “4.1 End-to-End Testing”">​</a></h3><p>At minimum, verify these scenarios:</p><ul><li>Student login → View exam list → Start exam → Submit → View grades</li><li>Admin login → Create exam → Add questions → Publish → View submission records</li></ul><h3 id="_4-2-deployment" tabindex="-1">4.2 Deployment <a class="header-anchor" href="#_4-2-deployment" aria-label="Permalink to “4.2 Deployment”">​</a></h3><ul><li>Frontend: Deploy to Vercel / Zeabur</li><li>Express API: Deploy to Zeabur / Railway / Render</li><li>Database: Use Supabase Postgres or managed PostgreSQL</li></ul><p>Pre-deployment checklist:</p><ul><li>[ ] Environment variables are complete</li><li>[ ] Frontend and backend API URLs are correct</li><li>[ ] Login state works in production</li><li>[ ] Admin account can actually access the dashboard</li><li>[ ] README includes setup, deployment, and testing instructions</li></ul><h2 id="deliverables" tabindex="-1">Deliverables <a class="header-anchor" href="#deliverables" aria-label="Permalink to “Deliverables”">​</a></h2><p>After completing this project, submit the following:</p><ul><li>[ ] Accessible live demo link</li><li>[ ] Source code repository link (with README)</li><li>[ ] PRD document</li><li>[ ] Core page screenshots (homepage, student exam list, exam-taking page, admin dashboard)</li><li>[ ] 60-second demo video (covering student exam flow and admin management flow)</li></ul><p>README should include at minimum: project overview, core page descriptions, tech stack, local setup steps, and environment variable list.</p><h2 id="grading-criteria" tabindex="-1">Grading Criteria <a class="header-anchor" href="#grading-criteria" aria-label="Permalink to “Grading Criteria”">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Basic Requirements</th><th>Advanced Requirements</th></tr></thead><tbody><tr><td>Page Completeness</td><td>Student and admin main pages are accessible</td><td>Unified page style, basic mobile responsiveness</td></tr><tr><td>Business Loop</td><td>Students can login, take exams, submit, and view grades</td><td>Admins can fully create and publish exams</td></tr><tr><td>Data Correctness</td><td>Submitted answers are saved to database, objective questions auto-graded</td><td>Short answers support manual review or AI assistance</td></tr><tr><td>Permission Control</td><td>Student and admin access boundaries are clear</td><td>Server-side APIs also have role verification</td></tr><tr><td>Engineering Delivery</td><td>Project runs and is deployable, README is clear</td><td>Has demo video and testing instructions</td></tr></tbody></table><h2 id="pre-submission-checklist" tabindex="-1">Pre-Submission Checklist <a class="header-anchor" href="#pre-submission-checklist" aria-label="Permalink to “Pre-Submission Checklist”">​</a></h2>`,51)),i(d,{shadow:"hover",style:{margin:"20px 0","border-radius":"12px"}},{header:l(()=>[...a[0]||(a[0]=[e("div",{style:{"font-weight":"bold","font-size":"16px"}},"Final check before submission",-1)])]),default:l(()=>[a[1]||(a[1]=e("ul",{style:{"list-style-type":"none","padding-left":"0"}},[e("li",null,[e("label",null,[e("input",{type:"checkbox",disabled:""}),s(" Homepage, login, student portal, and admin dashboard pages are complete")])]),e("li",null,[e("label",null,[e("input",{type:"checkbox",disabled:""}),s(" Students can start exams and submit answers normally")])]),e("li",null,[e("label",null,[e("input",{type:"checkbox",disabled:""}),s(" Admins can create exams and view submission records")])]),e("li",null,[e("label",null,[e("input",{type:"checkbox",disabled:""}),s(" Objective question scores are auto-calculated and saved to database")])]),e("li",null,[e("label",null,[e("input",{type:"checkbox",disabled:""}),s(" Student and admin permission boundaries are verified")])]),e("li",null,[e("label",null,[e("input",{type:"checkbox",disabled:""}),s(" Project is deployed or has complete local setup instructions")])])],-1))]),_:1}),a[4]||(a[4]=t('<h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI Design</a></li><li><a href="./../../frontend/modern-component-library/">Modern Component Libraries</a></li><li><a href="./../../backend/database-supabase/">Database to Supabase</a></li><li><a href="./../../backend/ai-interface-code/">API Code with LLM Assistance</a></li><li><a href="./../../backend/git-workflow/">Git &amp; GitHub Workflow</a></li><li><a href="./../../backend/zeabur-deployment/">Web App Deployment</a></li></ul>',2))])}const E=p(h,[["render",b]]);export{v as __pageData,E as default};
